import java.util.*;
import java.io.*;

public class MaxFlowSolver {
    static final int MAXN = 210;
    static final int INF = 0x3f3f3f3f;

    static class MaxFlow {
        int[][] capacity = new int[MAXN][MAXN];
        int[][] flow = new int[MAXN][MAXN];
        int[][] adj = new int[MAXN][MAXN];
        int[] degree = new int[MAXN];
        int nodeCount, source, sink;
        int[] height = new int[MAXN];
        int[] countHeight = new int[MAXN];
        int[] visited = new int[MAXN];
        int[] mark = new int[MAXN];

        void initialize(int n) {
            nodeCount = n;
            for (int i = 0; i <= n; i++) {
                Arrays.fill(capacity[i], 0);
                Arrays.fill(adj[i], 0);
                degree[i] = 0;
            }
        }

        void addEdge(int u, int v, int cap) {
            capacity[u][v] += cap;
            adj[u][v] = 1;
            if (adj[u][v] == 0) {
                adj[u][v] = 1;
                degree[u]++;
            }
        }

        int sendFlow(int u, int flowIn) {
            if (u == sink) return flowIn;
            int totalFlow = 0;
            for (int v = 0; v < nodeCount; v++) {
                if (capacity[u][v] - flow[u][v] > 0 && height[u] == height[v] + 1) {
                    int currFlow = Math.min(flowIn, capacity[u][v] - flow[u][v]);
                    int tempFlow = sendFlow(v, currFlow);
                    if (tempFlow > 0) {
                        flow[u][v] += tempFlow;
                        flow[v][u] -= tempFlow;
                        totalFlow += tempFlow;
                        flowIn -= tempFlow;
                        if (flowIn == 0) break;
                    }
                }
            }
            if (totalFlow == 0) {
                int minH = nodeCount;
                for (int v = 0; v < nodeCount; v++) {
                    if (capacity[u][v] - flow[u][v] > 0) minH = Math.min(minH, height[v]);
                }
                if (--countHeight[height[u]] == 0) height[source] = nodeCount;
                height[u] = minH + 1;
                countHeight[height[u]]++;
            }
            return totalFlow;
        }

        int maxFlow(int s, int t) {
            source = s;
            sink = t;
            for (int i = 0; i < nodeCount; i++) {
                Arrays.fill(flow[i], 0);
                height[i] = 0;
            }
            Arrays.fill(countHeight, 0);
            countHeight[0] = nodeCount;
            int total = 0;
            while (height[source] < nodeCount) {
                total += sendFlow(source, INF);
            }
            return total;
        }
    }

    static class Node {
        int x, y, step;
        Node(int x, int y, int step) {
            this.x = x;
            this.y = y;
            this.step = step;
        }
    }

    static int n, t;
    static int startX, startY;
    static final int[] dx = {0, 0, -1, 1};
    static final int[] dy = {-1, 1, 0, 0};
    static char[][] grid1 = new char[210][210];
    static char[][] grid2 = new char[210][210];
    static int[][] distFlag = new int[210][210];
    static int[][] visited = new int[210][210];

    static int ID(int i, int j) {
        return (i - 1) * n + j;
    }

    static boolean valid(int x, int y) {
        return x >= 1 && x <= n && y >= 1 && y <= n;
    }

    static void BFS1() {
        Queue<Node> q = new LinkedList<>();
        Node current = new Node(startX, startY, 0);
        for (int i = 0; i < 210; i++) {
            Arrays.fill(distFlag[i], Integer.MAX_VALUE);
            Arrays.fill(visited[i], 0);
        }
        visited[startX][startY] = 1;
        q.offer(current);
        while (!q.isEmpty()) {
            current = q.poll();
            distFlag[current.x][current.y] = current.step;
            if (current.step > t) break;
            for (int k = 0; k < 4; k++) {
                int nx = current.x + dx[k], ny = current.y + dy[k];
                if (valid(nx, ny) && grid1[nx][ny] != 'Y' && visited[nx][ny] == 0) {
                    visited[nx][ny] = 1;
                    q.offer(new Node(nx, ny, current.step + 1));
                }
            }
        }
    }

    static void BFS2(int i, int j, MaxFlow maxFlow) {
        Queue<Node> q = new LinkedList<>();
        Node current = new Node(i, j, 0);
        for (int k = 0; k < 210; k++) {
            Arrays.fill(visited[k], 0);
        }
        visited[i][j] = 1;
        q.offer(current);
        while (!q.isEmpty()) {
            current = q.poll();
            if (current.step > t) break;
            if (distFlag[current.x][current.y] < current.step) continue;
            if (distFlag[current.x][current.y] == current.step && (grid2[current.x][current.y] < '1' || grid2[current.x][current.y] > '9')) continue;
            if (grid2[current.x][current.y] >= '1' && grid2[current.x][current.y] <= '9') {
                if (current.x != i || current.y != j)
                    maxFlow.addEdge(ID(i, j), ID(current.x, current.y) + n * n, INF);
                if (distFlag[current.x][current.y] == current.step) continue;
            }
            for (int k = 0; k < 4; k++) {
                int nx = current.x + dx[k], ny = current.y + dy[k];
                if (valid(nx, ny) && grid1[nx][ny] != 'Y' && visited[nx][ny] == 0) {
                    visited[nx][ny] = 1;
                    q.offer(new Node(nx, ny, current.step + 1));
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());
        for (int i = 1; i <= n; i++) {
            String line = br.readLine();
            for (int j = 1; j <= n; j++) {
                grid1[i][j] = line.charAt(j - 1);
            }
        }
        for (int i = 1; i <= n; i++) {
            String line = br.readLine();
            for (int j = 1; j <= n; j++) {
                grid2[i][j] = line.charAt(j - 1);
            }
        }
        int s = 0;
        int e = 2 * n * n + 1;
        MaxFlow maxFlow = new MaxFlow();
        maxFlow.initialize(e + 1);
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (grid1[i][j] >= '1' && grid1[i][j] <= '9') {
                    maxFlow.addEdge(s, ID(i, j), grid1[i][j] - '0');
                }
                if (grid1[i][j] == 'Z') {
                    startX = i;
                    startY = j;
                }
            }
        }
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                maxFlow.addEdge(ID(i, j), ID(i, j) + n * n, INF);
                if (grid2[i][j] >= '1' && grid2[i][j] <= '9') {
                    maxFlow.addEdge(ID(i, j) + n * n, e, grid2[i][j] - '0');
                }
            }
        }
        BFS1();
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (grid1[i][j] >= '1' && grid1[i][j] <= '9') {
                    BFS2(i, j, maxFlow);
                }
            }
        }
        int result = maxFlow.maxFlow(s, e);
        System.out.println(result);
    }
}
